  "recipeIngredient": [
    "1 lb linguine (or spaghetti (good quality))",
    "3 Tbsp extra virgin olive oil",
    "3 cloves garlic (chopped)",
    "\u215b tsp cayenne pepper (fresh or dried (optional))",
    "1 small bunch Italian parsley (chopped)",
    "4 oz dry white wine",
    "1 lb littleneck clams ((fresh))",
    "\u215b tsp salt (to taste)",
    "\u215b tsp black pepper (to taste)"
  ],
  "recipeInstructions": [
    {
      "@type": "HowToStep",
      "position": 1,
      "name": "(Soak the clams in advance of making the recipe. I sprinkle a little Kosher salt into the water and leave for an hour or two. Afterwards scrub them well, and rinse. If any are open and don't close when tapped against a hard surface, discard.)",
      "text": "(Soak the clams in advance of making the recipe. I sprinkle a little Kosher salt into the water and leave for an hour or two. Afterwards scrub them well, and rinse. If any are open and don't close when tapped against a hard surface, discard.)",
      "image": null,
      "imageCredit": null
    },
    {
      "@type": "HowToStep",
      "position": 2,
      "name": "Before starting to cook the clams, pop the pasta into a pot of salted water at a rolling boil. Cook according to the time on the package to \"al dente\", when the inside of the pasta is still a little hard.",
      "text": "Before starting to cook the clams, pop the pasta into a pot of salted water at a rolling boil. Cook according to the time on the package to \"al dente\", when the inside of the pasta is still a little hard.",
      "image": null,
      "imageCredit": null
    },
    {
      "@type": "HowToStep",
      "position": 3,
      "name": "Chop the garlic and parsley and add a little cayenne pepper, too, if you like.",
      "text": "Chop the garlic and parsley and add a little cayenne pepper, too, if you like.",
      "image": null,
      "imageCredit": null
    },
    {
      "@type": "HowToStep",
      "position": 4,
      "name": "In a pan over medium high heat, add the garlic, then the parsley and hot pepper, if using.",
      "text": "In a pan over medium high heat, add the garlic, then the parsley and hot pepper, if using.",
      "image": null,
      "imageCredit": null
    },
    {
      "@type": "HowToStep",
      "position": 5,
      "name": "Before the garlic starts to brown, add the wine. Next, add the clams, and cover.",
      "text": "Before the garlic starts to brown, add the wine. Next, add the clams, and cover.",
      "image": null,
      "imageCredit": null
    },
    {
      "@type": "HowToStep",
      "position": 6,
      "name": "Cook just as long as needed for them to open: usually about 5 minutes, but no more than 8 or 9 minutes (the larger the clams, the longer the cook time). Discard any that do not open at all. When ready, turn off the heat.",
      "text": "Cook just as long as needed for them to open: usually about 5 minutes, but no more than 8 or 9 minutes (the larger the clams, the longer the cook time). Discard any that do not open at all. When ready, turn off the heat.",
      "image": null,
      "imageCredit": null
    },
    {
      "@type": "HowToStep",
      "position": 7,
      "name": "Immediately add the linguine or spaghetti, straight from the pot using a pasta fork (do not drain the pasta unless you reserve a cup of the cooking water).",
      "text": "Immediately add the linguine or spaghetti, straight from the pot using a pasta fork (do not drain the pasta unless you reserve a cup of the cooking water).",
      "image": null,
      "imageCredit": null
    },
    {
      "@type": "HowToStep",
      "position": 8,
      "name": "Stir and toss to mix in the pasta with the clam sauce, adding some of the pasta water if needed (if it's too dry, it needs it). Serve immediately.",
      "text": "Stir and toss to mix in the pasta with the clam sauce, adding some of the pasta water if needed (if it's too dry, it needs it). Serve immediately.",
